--
-- Table structure for table `attr_ue_classe`
--

DROP TABLE IF EXISTS `attr_ue_classe`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `attr_ue_classe` (
  `Id_Attr_ue_Sem` int NOT NULL AUTO_INCREMENT,
  `id_Annee_Acad` int NOT NULL,
  `id_S_Gr_Spe` int NOT NULL,
  `codeUe` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `Id_Cat_Ue` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `idImportance` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `Seuil_Ue` float(10,2) NOT NULL,
  `Credit` float(10,2) NOT NULL,
  `Auteur` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `Moment` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`Id_Attr_ue_Sem`),
  UNIQUE KEY `id_Annee_Acad_2` (`id_Annee_Acad`,`id_S_Gr_Spe`,`codeUe`,`Id_Cat_Ue`,`idImportance`),
  KEY `codeUe` (`codeUe`),
  KEY `Id_Cat_Ue` (`Id_Cat_Ue`),
  KEY `idImportance` (`idImportance`),
  KEY `id_Annee_Acad` (`id_Annee_Acad`,`id_S_Gr_Spe`),
  KEY `id_S_Gr_Spe` (`id_S_Gr_Spe`),
  CONSTRAINT `attr_ue_classe_ibfk_1` FOREIGN KEY (`id_Annee_Acad`) REFERENCES `anneeacademique` (`id_Annee_Acad`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `attr_ue_classe_ibfk_2` FOREIGN KEY (`id_S_Gr_Spe`) REFERENCES `classe` (`id_S_Gr_Spe`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `attr_ue_classe_ibfk_3` FOREIGN KEY (`codeUe`) REFERENCES `ue` (`codeUe`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `attr_ue_classe_ibfk_4` FOREIGN KEY (`Id_Cat_Ue`) REFERENCES `categorie_ue` (`Id_Cat_Ue`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `attr_ue_classe_ibfk_5` FOREIGN KEY (`idImportance`) REFERENCES `importance` (`idImportance`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=588 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
