DROP TABLE IF EXISTS `evaluation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `evaluation` (
  `numeroEval` int NOT NULL AUTO_INCREMENT,
  `dateEval` date DEFAULT NULL,
  `heureDebutEval` time DEFAULT NULL,
  `dureeEval` int DEFAULT NULL,
  `codeGroupe` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Id_Attr_ue_Sem` int NOT NULL,
  `codeEcu` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `codTypEval` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `effectuer` int DEFAULT '0',
  `corriger` int NOT NULL DEFAULT '0',
  `version` int DEFAULT '1',
  `login` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`numeroEval`),
  KEY `FKEVALUATION81458` (`codTypEval`),
  KEY `FKEVALUATION310890` (`codeEcu`),
  KEY `Id_Attr_ue_Sem` (`Id_Attr_ue_Sem`,`codeEcu`)
) ENGINE=InnoDB AUTO_INCREMENT=1925 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
